+import type { InvoiceLine } from "./classify.ts";
+
+const COLUMNS = ["description", "supplier", "quantity", "unit", "amount"] as const;
+type Column = (typeof COLUMNS)[number];
+
+function isColumn(name: string): name is Column {
+  return (COLUMNS as readonly string[]).includes(name);
+}
+
+/** Parses Finnish-formatted numbers such as `1 840,00` or `-12,5`. */
+function parseNumber(cell: string, column: Column, lineNo: number): number {
+  const normalized = cell.replace(/[\s  ]/g, "").replace(",", ".");
+  if (!/^[+-]?(\d+\.?\d*|\.\d+)$/.test(normalized)) {
+    throw new Error(`line ${lineNo}: invalid ${column} ${JSON.stringify(cell)}`);
+  }
+  return Number(normalized);
+}
+
+/**
+ * Parses semicolon-separated invoice lines. The header must only contain
+ * description, supplier, quantity, unit and amount; empty cells are omitted.
+ */
+export function parseInvoiceCsv(text: string): InvoiceLine[] {
+  const rows = text
+    .replace(/^﻿/, "")
+    .split(/\r\n|\r|\n/)
+    .map((raw, i) => ({ raw, lineNo: i + 1 }))
+    .filter((r) => r.raw.trim() !== "");
+  if (rows.length === 0) return [];
+
+  const header = rows[0].raw.split(";").map((h) => h.trim());
+  for (const h of header) {
+    if (!isColumn(h)) throw new Error(`unknown column ${JSON.stringify(h)}`);
+  }
+  const columns = header as Column[];
+
+  return rows.slice(1).map(({ raw, lineNo }) => {
+    const cells = raw.split(";").map((c) => c.trim());
+    const line: InvoiceLine = { description: "" };
+    columns.forEach((col, i) => {
+      const cell = cells[i] ?? "";
+      if (cell === "") return;
+      if (col === "quantity" || col === "amount") line[col] = parseNumber(cell, col, lineNo);
+      else line[col] = cell;
+    });
+    return line;
+  });
+}
