+import { describe, expect, it } from "vitest";
+import { parseInvoiceCsv } from "../src/csv.ts";
+
+const H = "description;supplier;quantity;unit;amount";
+
+describe("parseInvoiceCsv", () => {
+  it("parses rows with Finnish numbers and omits empty cells", () => {
+    const out = parseInvoiceCsv(`${H}\nBetoni C30;Rudus;12,5;m3;1 840,00\n\nVuokra;;;;-99,9\n`);
+    expect(out).toEqual([
+      { description: "Betoni C30", supplier: "Rudus", quantity: 12.5, unit: "m3", amount: 1840 },
+      { description: "Vuokra", amount: -99.9 },
+    ]);
+  });
+  it("handles CRLF", () => {
+    expect(parseInvoiceCsv(`${H}\r\nA;B;1;kpl;2,00\r\n`)).toHaveLength(1);
+  });
+  it("throws on unknown column", () => {
+    expect(() => parseInvoiceCsv("description;foo\nA;B")).toThrow(/foo/);
+  });
+  it("throws on bad number", () => {
+    expect(() => parseInvoiceCsv(`${H}\nA;B;abc;kpl;1`)).toThrow(/quantity/);
+    expect(() => parseInvoiceCsv(`${H}\nA;B;1;kpl;1,2,3`)).toThrow(/amount/);
+  });
+});

