+/**
+ * Split a gross (VAT-inclusive) amount into net and VAT, both rounded to cents.
+ * Any rounding difference goes into `vat`, so `net + vat === gross` in cents.
+ */
+export function splitVat(gross: number, ratePercent = 25.5): { net: number; vat: number } {
+  if (!Number.isFinite(gross)) throw new Error(`invalid gross amount: ${gross}`);
+  if (!Number.isFinite(ratePercent) || ratePercent < 0) {
+    throw new Error(`invalid VAT rate: ${ratePercent}`);
+  }
+  const grossCents = Math.round(gross * 100);
+  const netCents = Math.round(grossCents / (1 + ratePercent / 100));
+  return { net: netCents / 100, vat: (grossCents - netCents) / 100 };
+}
