+import { describe, expect, it } from "vitest";
+import { splitVat } from "../src/vat.ts";
+
+describe("splitVat", () => {
+  it("splits at the default 25.5% rate", () => {
+    expect(splitVat(125.5)).toEqual({ net: 100, vat: 25.5 });
+  });
+  it("keeps net + vat equal to gross in cents", () => {
+    for (const g of [0.01, 1, 9.99, 33.33, 100, 1234.56, -19.99]) {
+      const { net, vat } = splitVat(g);
+      expect(Math.round(net * 100) + Math.round(vat * 100)).toBe(Math.round(g * 100));
+    }
+  });
+  it("handles zero rate", () => {
+    expect(splitVat(10, 0)).toEqual({ net: 10, vat: 0 });
+  });
+  it("throws on negative rates", () => {
+    expect(() => splitVat(10, -1)).toThrow();
+  });
+});
